  1	/**
  2	 * Queue reading internals for the orchestrator run queue (WP-B extraction).
  3	 *
  4	 * Reads `.run-queue.json`, enriches each raw entry with computed lifecycle
  5	 * state and JSONL progress data, and returns the result as `QueueEntry[]`.
  6	 *
  7	 * This module is read-only with respect to the queue file and all other files.
  8	 *
  9	 * The `isRawQueueEntry` type-guard has been extracted to `validate-entry.ts`
 10	 * for direct testability; it is imported here and re-used at the filter call site.
 11	 *
 12	 * Exports beyond `getQueue()`:
 13	 *   - `readQueueFile` — used by `checkNoConflict` in `orchestrator-manager.ts`.
 14	 *   - `isProcessAlive` — used by queue-mutation functions in `orchestrator-manager.ts`.
 15	 *   - `getProjectLedgerStatus` — used by `killQueueEntry`/`dismissQueueEntry`
 16	 *     in `orchestrator-manager.ts`.
 17	 *
 18	 * Ledger path layout — dual-mode (introduced in WP-007):
 19	 *   `getProjectLedgerStatus()` supports two path layouts depending on whether
 20	 *   the queue entry carries an `expectedRepo` (multi-root workspace) value:
 21	 *
 22	 *   • Namespaced (expectedRepo non-null):
 23	 *       `<ledgerRoot>/<expectedRepo>/<slug>/project-ledger.json`
 24	 *   • Flat / legacy (expectedRepo null):
 25	 *       `<ledgerRoot>/<slug>/project-ledger.json`
 26	 *
 27	 *   All three call sites — `getQueue()`, `killQueueEntry()`, and
 28	 *   `dismissQueueEntry()` — pass `entry.expectedRepo` as the third argument,
 29	 *   so the correct layout is selected automatically per entry.
 30	 */
 31	
 32	import { readFile } from 'node:fs/promises';
 33	import { join } from 'node:path';
 34	
 35	import { QUEUE_FILENAME, type RawQueueEntry, type QueueEntry } from './types.js';
 36	import { isRawQueueEntry } from './validate-entry.js';
 37	import { resolveProgress } from './resolve-progress.js';
 38	import { computeEffectiveStatus } from './compute-effective-status.js';
 39	
 40	// ---------------------------------------------------------------------------
 41	// PID alive check
 42	// ---------------------------------------------------------------------------
 43	
 44	/**
 45	 * Returns `true` if the process with `pid` exists on this machine.
 46	 *
 47	 * Uses `process.kill(pid, 0)` which is a zero-signal check — it only
 48	 * verifies the process exists and does not actually deliver any signal.
 49	 *
 50	 * Exported for use by queue-mutation functions in `orchestrator-manager.ts`.
 51	 */
 52	export function isProcessAlive(pid: number): boolean {
 53	  try {
 54	    process.kill(pid, 0);
 55	    return true;
 56	  } catch {
 57	    return false;
 58	  }
 59	}
 60	
 61	// ---------------------------------------------------------------------------
 62	// Queue file reader
 63	// ---------------------------------------------------------------------------
 64	
 65	/**
 66	 * Reads and parses `<logsDir>/.run-queue.json`.
 67	 * Returns `[]` on any I/O or parse error — fail-safe.
 68	 * Never writes to the queue file.
 69	 *
 70	 * Exported for use by `checkNoConflict` in `orchestrator-manager.ts`.
 71	 */
 72	export async function readQueueFile(logsDir: string): Promise<RawQueueEntry[]> {
 73	  const queuePath = join(logsDir, QUEUE_FILENAME);
 74	  let raw: string;
 75	  try {
 76	    raw = await readFile(queuePath, 'utf-8');
 77	  } catch {
 78	    return [];
 79	  }
 80	  try {
 81	    const data: unknown = JSON.parse(raw);
 82	    if (!Array.isArray(data)) return [];
 83	    return data.filter(isRawQueueEntry);
 84	  } catch {
 85	    return [];
 86	  }
 87	}
 88	
 89	// ---------------------------------------------------------------------------
 90	// Project ledger check
 91	// ---------------------------------------------------------------------------
 92	
 93	/**
 94	 * Returns whether the project identified by `slug` (and optionally `expectedRepo`)
 95	 * has a ledger entry and whether synthesis has been generated for it.
 96	 *
 97	 * When `expectedRepo` is non-null the function constructs a namespaced path:
 98	 *   `<ledgerRoot>/<expectedRepo>/<slug>/project-ledger.json`
 99	 *
100	 * When `expectedRepo` is null it falls back to the legacy flat path for

101	 * backward compatibility with queue entries that pre-date multi-root workspace
102	 * support:
103	 *   `<ledgerRoot>/<slug>/project-ledger.json`
104	 *
105	 * Fail-safe: any I/O or parse error returns `{ exists: false, synthesisGenerated: false }`.
106	 *
107	 * Exported for use by `killQueueEntry`/`dismissQueueEntry` in `orchestrator-manager.ts`.
108	 *
109	 * @param ledgerRoot   - Absolute path to the ledger root directory.
110	 * @param slug         - Project slug (e.g. `2026-05-05-my-feature`).
111	 * @param expectedRepo - Repository name (workspace root slug), or `null` for
112	 *                       legacy flat-path lookup.
113	 * @returns An object with two fields:
114	 *   - `exists` — `true` when the `project-ledger.json` file is present and
115	 *     readable; `false` on any I/O error or when the file does not exist.
116	 *   - `synthesisGenerated` — `true` when the ledger's `synthesis_generated` field equals
117	 *     `true`; `false` when the file is absent, unreadable, or the field is falsy.
118	 */
119	export async function getProjectLedgerStatus(
120	  ledgerRoot: string,
121	  slug: string,
122	  expectedRepo: string | null = null,
123	): Promise<{ exists: boolean; synthesisGenerated: boolean }> {
124	  const projectLedgerPath = expectedRepo
125	    ? join(ledgerRoot, expectedRepo, slug, 'project-ledger.json')
126	    : join(ledgerRoot, slug, 'project-ledger.json');
127	  let raw: string;
128	  try {
129	    raw = await readFile(projectLedgerPath, 'utf-8');
130	  } catch {
131	    return { exists: false, synthesisGenerated: false };
132	  }
133	  try {
134	    const data = JSON.parse(raw) as Record<string, unknown>;
135	    return {
136	      exists: true,
137	      synthesisGenerated: data['synthesis_generated'] === true,
138	    };
139	  } catch {
140	    return { exists: true, synthesisGenerated: false };
141	  }
142	}
143	
144	// ---------------------------------------------------------------------------
145	// Public API
146	// ---------------------------------------------------------------------------
147	
148	/**
149	 * Reads the shared orchestrator run queue and returns all active entries
150	 * enriched with computed lifecycle state and JSONL progress summaries.
151	 *
152	 * Entries for completed projects (`synthesis_generated === true`) are
153	 * automatically excluded from the result.
154	 *
155	 * This function is read-only: it never writes to the queue file or any
156	 * other file on disk.
157	 *
158	 * @param params.logsDir    - Absolute path to `orchestrator/logs/`.
159	 * @param params.ledgerRoot - Absolute path to the central ledger root.
160	 * @returns Enriched queue entries, excluding completed runs.
161	 */
162	export async function getQueue(params: {
163	  logsDir: string;
164	  ledgerRoot: string;
165	}): Promise<QueueEntry[]> {
166	  const { logsDir, ledgerRoot } = params;
167	
168	  const rawEntries = await readQueueFile(logsDir);
169	  if (rawEntries.length === 0) return [];
170	
171	  const enriched = await Promise.all(
172	    rawEntries.map(async (entry) => {
173	      const [projectStatus, progressResult] = await Promise.all([
174	        getProjectLedgerStatus(ledgerRoot, entry.expectedSlug, entry.expectedRepo),
175	        resolveProgress(logsDir, entry.expectedSlug),
176	      ]);
177	
178	      const { exists: projectExists, synthesisGenerated } = projectStatus;
179	      const alive = isProcessAlive(entry.pid);
180	
181	      // Compute effective status per AC-2 through AC-5.
182	      const effectiveStatus = computeEffectiveStatus(alive, projectExists, progressResult.hasStageActivity);
183	
184	      // AC-6: exclude entries whose project has completed synthesis.
185	      if (effectiveStatus === 'started' && synthesisGenerated) {
186	        return null;
187	      }
188	
189	      const result: QueueEntry = {
190	        ...entry,
191	        effectiveStatus,
192	        progress:      progressResult.summary,
193	        lastAction:    progressResult.lastAction,
194	        logFilename:   progressResult.logFilename,
195	        projectExists,
196	      };
197	      return result;
198	    }),
199	  );

