  1	/**
  2	 * Tests for src/gui/queue/get-queue.ts — WP-005 + WP-001 (rework)
  3	 *
  4	 * Verifies:
  5	 *   AC-1 (WP-005): getQueue() returns entries with projectExists: true when the
  6	 *         project ledger file exists on disk.
  7	 *   AC-2 (WP-005): getQueue() returns entries with projectExists: false when no
  8	 *         project ledger file exists for the entry's expectedSlug.
  9	 *   AC-3 (WP-001 rework — validator): isRawQueueEntry() rejects entries whose
 10	 *         expectedSlug is an empty string or a whitespace-only string (e.g. '   ').
 11	 *         getQueue() returns an empty array for such malformed entries.
 12	 */
 13	
 14	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
 15	import { mkdtemp, mkdir, rm, writeFile } from 'node:fs/promises';
 16	import { join } from 'node:path';
 17	import { tmpdir } from 'node:os';
 18	
 19	import { getQueue } from '../../../src/gui/queue/get-queue.js';
 20	import { QUEUE_FILENAME } from '../../../src/gui/queue/types.js';
 21	
 22	// ---------------------------------------------------------------------------
 23	// Helpers
 24	// ---------------------------------------------------------------------------
 25	
 26	interface TestEnv {
 27	  tempDir: string;
 28	  logsDir: string;
 29	  ledgerRoot: string;
 30	}
 31	
 32	async function setup(): Promise<TestEnv> {
 33	  const tempDir    = await mkdtemp(join(tmpdir(), 'get-queue-test-'));
 34	  const logsDir    = join(tempDir, 'logs');
 35	  const ledgerRoot = join(tempDir, 'ledger');
 36	  await mkdir(logsDir,    { recursive: true });
 37	  await mkdir(ledgerRoot, { recursive: true });
 38	  return { tempDir, logsDir, ledgerRoot };
 39	}
 40	
 41	async function teardown(tempDir: string): Promise<void> {
 42	  await rm(tempDir, { recursive: true, force: true });
 43	}
 44	
 45	/**
 46	 * Writes a minimal `.run-queue.json` with a single entry whose PID is
 47	 * intentionally unreachable. Avoid PID 0 — `process.kill(0, 0)` targets the
 48	 * current process group on POSIX systems. Use a very large integer that is
 49	 * almost certainly unused instead.
 50	 */
 51	async function writeQueue(logsDir: string, slug: string, pid = 999_999_999): Promise<void> {
 52	  const entry = {
 53	    id:          'test-id-1',
 54	    pid,
 55	    planPath:    `/fake/plans/${slug}`,
 56	    expectedSlug: slug,
 57	    startedAt:   '2026-05-20T00:00:00Z',
 58	    status:      'pending',
 59	  };
 60	  await writeFile(join(logsDir, QUEUE_FILENAME), JSON.stringify([entry]), 'utf-8');
 61	}
 62	
 63	/**
 64	 * Creates a minimal project-ledger.json at `<ledgerRoot>/<slug>/project-ledger.json`.
 65	 */
 66	async function createProjectLedger(ledgerRoot: string, slug: string): Promise<void> {
 67	  const projectDir = join(ledgerRoot, slug);
 68	  await mkdir(projectDir, { recursive: true });
 69	  await writeFile(
 70	    join(projectDir, 'project-ledger.json'),
 71	    JSON.stringify({ synthesis_generated: false }),
 72	    'utf-8',
 73	  );
 74	}
 75	
 76	// ---------------------------------------------------------------------------
 77	// AC-1: projectExists is true when the ledger file exists
 78	// ---------------------------------------------------------------------------
 79	
 80	describe('getQueue — AC-1: projectExists is true when ledger file exists', () => {
 81	  let env: TestEnv;
 82	
 83	  beforeEach(async () => {
 84	    env = await setup();
 85	  });
 86	
 87	  afterEach(async () => {
