166	  });
167	
168	  it('filters out an entry whose expectedSlug is whitespace-only', async () => {
169	    // Write a queue with one entry that has a whitespace-only expectedSlug.
170	    const invalidEntry = {
171	      id:           'test-whitespace-slug',
172	      pid:          999_999_999,
173	      planPath:     '/fake/plans/whitespace-slug',
174	      expectedSlug: '   ',
175	      startedAt:    '2026-05-20T00:00:00Z',
